    return new ProtocolProxy<T>(protocol,
        (T) getProxy(protocol, clientVersion, connectionId, conf, factory,
            alignmentContext), true);
  }

  static <T> T getProxy(Class<T> protocol, long clientVersion,
      Client.ConnectionId connId, Configuration conf, SocketFactory factory,
      AlignmentContext alignmentContext) {
    return getProtocolEngine(protocol, conf).getProxy(protocol, clientVersion,
        connId, conf, factory, alignmentContext);
  }
```

